from __future__ import annotations

import base64
import importlib.util
import json
import logging
from pathlib import Path

import pytest
from fastapi.testclient import TestClient


MODULE_PATH = Path("runs/kit/REQ-002/src/backend/auth/main_module.py")


def _load_module():
    spec = importlib.util.spec_from_file_location("req002_auth_main_module", MODULE_PATH)
    module = importlib.util.module_from_spec(spec)
    assert spec is not None
    assert spec.loader is not None
    spec.loader.exec_module(module)
    return module


@pytest.fixture()
def auth_module():
    return _load_module()


def _jwt_for_claims(claims: dict[str, object]) -> str:
    header = {"alg": "none", "typ": "JWT"}

    def _segment(value: dict[str, object]) -> str:
        encoded = base64.urlsafe_b64encode(json.dumps(value).encode("utf-8")).decode("utf-8")
        return encoded.rstrip("=")

    return f"{_segment(header)}.{_segment(claims)}."


def _bearer_headers(claims: dict[str, object]) -> dict[str, str]:
    return {"Authorization": f"Bearer {_jwt_for_claims(claims)}"}


def _saml_assertion(
    *,
    issuer: str,
    nameid: str,
    attributes: dict[str, str | list[str]],
) -> str:
    attribute_blocks = []
    for name, raw_value in attributes.items():
        values = raw_value if isinstance(raw_value, list) else [raw_value]
        attribute_values = "".join(
            f"<AttributeValue>{value}</AttributeValue>" for value in values
        )
        attribute_blocks.append(f'<Attribute Name="{name}">{attribute_values}</Attribute>')

    xml = (
        "<Assertion>"
        f"<Issuer>{issuer}</Issuer>"
        "<Subject>"
        f"<NameID>{nameid}</NameID>"
        "</Subject>"
        "<AttributeStatement>"
        f"{''.join(attribute_blocks)}"
        "</AttributeStatement>"
        "</Assertion>"
    )
    return base64.b64encode(xml.encode("utf-8")).decode("utf-8")


class RecordingWriter:
    def __init__(self) -> None:
        self.calls: list[dict[str, object]] = []

    def write(self, *, actor, payload):
        entry = {
            "actor_id": actor.actor_id,
            "username": actor.username,
            "payload": dict(payload),
        }
        self.calls.append(entry)
        return {"stored": True, "actor_id": actor.actor_id}


class RecordingAuditor:
    def __init__(self) -> None:
        self.calls: list[dict[str, object]] = []

    def record(self, *, actor, action, payload):
        self.calls.append(
            {
                "actor_id": actor.actor_id,
                "username": actor.username,
                "action": action,
                "payload": dict(payload),
            }
        )


def test_map_idp_claims_to_permission_set_deterministically(auth_module):
    oidc_actor = auth_module.normalize_actor_context(
        {
            "iss": "https://issuer.example/oidc",
            "sub": "user-123",
            "preferred_username": "ada",
            "name": "Ada Lovelace",
            "groups": ["slice1-reader", "slice1-validator"],
        },
        claims_source="oidc",
        permission_map=auth_module.DEFAULT_PERMISSION_MAP,
    )

    assert oidc_actor.actor_id == "https://issuer.example/oidc:user-123"
    assert oidc_actor.username == "ada"
    assert oidc_actor.display_name == "Ada Lovelace"
    assert oidc_actor.permission_refs == ("slice1-reader", "slice1-validator")
    assert oidc_actor.permissions == ("documents:read", "tasks:validate")

    saml_claims = auth_module.parse_saml_assertion(
        _saml_assertion(
            issuer="https://issuer.example/saml",
            nameid="validator-7",
            attributes={
                "display_name": "Grace Hopper",
                "roles": ["slice1-admin"],
            },
        )
    )
    saml_actor = auth_module.normalize_actor_context(
        saml_claims,
        claims_source="saml",
        permission_map=auth_module.DEFAULT_PERMISSION_MAP,
    )

    assert saml_actor.actor_id == "https://issuer.example/saml:validator-7"
    assert saml_actor.display_name == "Grace Hopper"
    assert saml_actor.permission_refs == ("slice1-admin",)
    assert saml_actor.permissions == (
        "documents:read",
        "documents:write",
        "tasks:validate",
    )


def test_deny_when_required_permission_missing(auth_module):
    writer = RecordingWriter()
    auditor = RecordingAuditor()
    client = TestClient(auth_module.create_app(writer=writer, auditor=auditor))

    response = client.post(
        "/documents/write-test",
        headers=_bearer_headers(
            {
                "iss": "https://issuer.example/oidc",
                "sub": "reader-1",
                "preferred_username": "reader.only",
                "groups": ["slice1-reader"],
            }
        ),
        json={"document_id": "doc-1"},
    )

    assert response.status_code == 403
    assert response.json()["detail"]["error"] == "forbidden"
    assert response.json()["detail"]["missing_permissions"] == ["documents:write"]
    assert writer.calls == []
    assert auditor.calls == []


def test_get_auth_me_returns_normalized_actor_for_fixture_identity(auth_module):
    client = TestClient(auth_module.create_app())

    response = client.get(
        "/auth/me",
        headers=_bearer_headers(
            {
                "iss": "https://issuer.example/oidc",
                "sub": "validator-1",
                "preferred_username": "v.one",
                "name": "Validator One",
                "groups": ["slice1-validator"],
            }
        ),
    )

    assert response.status_code == 200
    assert response.json() == {
        "actor_id": "https://issuer.example/oidc:validator-1",
        "subject": "validator-1",
        "username": "v.one",
        "display_name": "Validator One",
        "identity_provider": "https://issuer.example/oidc",
        "claims_source": "oidc",
        "permission_refs": ["slice1-validator"],
        "permissions": ["documents:read", "tasks:validate"],
    }


@pytest.mark.parametrize(
    ("headers", "expected_status"),
    [
        ({}, 401),
        (
            _bearer_headers(
                {
                    "iss": "https://issuer.example/oidc",
                    "sub": "reader-2",
                    "preferred_username": "reader.two",
                    "groups": ["slice1-reader"],
                }
            ),
            403,
        ),
    ],
)
def test_protected_endpoint_returns_401_anonymous_and_403_unauthorized(
    auth_module,
    headers,
    expected_status,
):
    writer = RecordingWriter()
    auditor = RecordingAuditor()
    client = TestClient(auth_module.create_app(writer=writer, auditor=auditor))

    response = client.post("/documents/write-test", headers=headers, json={"document_id": "doc-2"})

    assert response.status_code == expected_status
    assert writer.calls == []
    assert auditor.calls == []


def test_actor_identity_propagates_to_downstream_audit_and_write_paths(auth_module):
    writer = RecordingWriter()
    auditor = RecordingAuditor()
    client = TestClient(auth_module.create_app(writer=writer, auditor=auditor))

    response = client.post(
        "/documents/write-test",
        headers=_bearer_headers(
            {
                "iss": "https://issuer.example/oidc",
                "sub": "admin-1",
                "preferred_username": "admin.one",
                "groups": ["slice1-admin"],
            }
        ),
        json={"document_id": "doc-3", "mutation": "store"},
    )

    assert response.status_code == 200
    assert response.json()["status"] == "ok"
    assert response.json()["actor_id"] == "https://issuer.example/oidc:admin-1"

    assert writer.calls == [
        {
            "actor_id": "https://issuer.example/oidc:admin-1",
            "username": "admin.one",
            "payload": {"document_id": "doc-3", "mutation": "store"},
        }
    ]
    assert auditor.calls == [
        {
            "actor_id": "https://issuer.example/oidc:admin-1",
            "username": "admin.one",
            "action": "documents.write_test",
            "payload": {"document_id": "doc-3", "mutation": "store"},
        }
    ]


def test_tokens_and_assertions_are_redacted_in_logs(auth_module, caplog):
    client = TestClient(auth_module.create_app())
    caplog.set_level(logging.WARNING)

    raw_bearer = "this-is-not-a-jwt"
    raw_assertion = "definitely-not-base64-xml"

    bearer_response = client.get(
        "/auth/me",
        headers={"Authorization": f"Bearer {raw_bearer}"},
    )
    saml_response = client.get(
        "/auth/me",
        headers={"X-SAML-Assertion": raw_assertion},
    )

    assert bearer_response.status_code == 401
    assert saml_response.status_code == 401

    log_output = "\n".join(record.getMessage() for record in caplog.records)
    assert raw_bearer not in log_output
    assert raw_assertion not in log_output
    assert "<redacted len=" in log_output

